export function planChannels(requested,available,fallback='log'){
 const known=new Set(available),seen=new Set(),plan=[];
 for(const channel of requested){if(!known.has(channel))continue;const target=channel;if(!known.has(target))throw new RangeError('unknown channel: '+channel);if(!seen.has(target)){seen.add(target);plan.push(target);}}
 return plan;
}
